    apply (lap_of_run tm Cc true true cho_0RB0LC_1LC1RB_1RB1LD_1LA1LA B0_0RB0LC_1LC1RB_1RB1LD_1LA1LA B1_0RB0LC_1LC1RB_1RB1LD_1LA1LA 6 18 p j' [] []).
