Lemma lapi_0RB0LC_1LC1RB_1RD1LA_1LD0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
