  { unfold Cin_0RB0LC_1LC1RB_1RD1LA_1LD0RC. rewrite epow2_0RB0LC_1LC1RB_1RD1LA_1LD0RC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LC_1LC1RB_1RD1LA_1LD0RC. rewrite ?lift_app_blank. reflexivity.
