Lemma fire_0RB0LC_1LC1RD_1RC1LA_0LD1RB : forall t, ~ In t pins_0RB0LC_1LC1RD_1RC1LA_0LD1RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
