  - exists (6 * j + 14), (cden [] [] j BB1_0RB0LC_1RC0RB_1LA0RD_0LB0LA).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1RC0RB_1LA0RD_0LB0LA j)].
    rewrite (gso_0RB0LC_1RC0RB_1LA0RD_0LB0LA p j E).
    exact (srun_sound tm true true chb_0RB0LC_1RC0RB_1LA0RD_0LB0LA B0_0RB0LC_1RC0RB_1LA0RD_0LB0LA BB1_0RB0LC_1RC0RB_1LA0RD_0LB0LA 6 14
             run_boot_0RB0LC_1RC0RB_1LA0RD_0LB0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 12), (cden [] [] j B1_0RB0LC_1RC0RB_1LA0RD_0LB0LA).
    split; [| exact (geo_0RB0LC_1RC0RB_1LA0RD_0LB0LA p j E)].
    rewrite (gxi_0RB0LC_1RC0RB_1LA0RD_0LB0LA j).
    exact (srun_sound tm true true che_0RB0LC_1RC0RB_1LA0RD_0LB0LA BE0_0RB0LC_1RC0RB_1LA0RD_0LB0LA B1_0RB0LC_1RC0RB_1LA0RD_0LB0LA 6 12
             run_exit_0RB0LC_1RC0RB_1LA0RD_0LB0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_1RC0RB_1LA0RD_0LB0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
