  - destruct (lapi_0RB0LC_1RC0RB_1LA0RD_0LB0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_1RC0RB_1LA0RD_0LB0LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_1RC0RB_1LA0RD_0LB0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 7.
  assert (H : match csteps tm 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1RC0RB_1LA0RD_0LB0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1RC0RB_1LA0RD_0LB0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1RC0RB_1LA0RD_0LB0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1RC0RB_1LA0RD_0LB0LA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB0LC_1RC0RB_1LA0RD_0LB0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0LC_1RC0RB_1LA0RD_0LB0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB0LC_1RC0RB_1LA0RD_0LB0LA t p (pow2 j)).
  - exists (6 * j + 14), (cden [] [] j BB1_0RB0LC_1RC0RB_1LA0RD_0LB0LA). split;
      [| exact (gbo_0RB0LC_1RC0RB_1LA0RD_0LB0LA j)].
    rewrite (gso_0RB0LC_1RC0RB_1LA0RD_0LB0LA p j E).
    exact (srun_sound tm true true chb_0RB0LC_1RC0RB_1LA0RD_0LB0LA B0_0RB0LC_1RC0RB_1LA0RD_0LB0LA BB1_0RB0LC_1RC0RB_1LA0RD_0LB0LA 6 14
             run_boot_0RB0LC_1RC0RB_1LA0RD_0LB0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB0LC_1RC0RB_1LA0RD_0LB0LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB0LC_1RC0RB_1LA0RD_0LB0LA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1RC0RB_1LA0RD_0LB0LA : forall t, ~ In t pins_0RB0LC_1RC0RB_1LA0RD_0LB0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
