(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LC_1RC0RB_1LA0RD_1LC0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ip q0 ++ [S0]) [] j A0_0RB0LC_1RC0RB_1LA0RD_1LC0LA.
