  unfold Cin_0RB0LC_1RC0RB_1LA0RD_1LC0LA, cden, BE0_0RB0LC_1RC0RB_1LA0RD_1LC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
