  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_0RB0LC_1RC0RB_1LA0RD_1LC0LA. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LC_1RC0RB_1LA0RD_1LC0LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_1RC0RB_1LA0RD_1LC0LA p (pow2 j)).
  - exists (6 * j + 8), (cden [] [] j BB1_0RB0LC_1RC0RB_1LA0RD_1LC0LA).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1RC0RB_1LA0RD_1LC0LA j)].
    rewrite (gso_0RB0LC_1RC0RB_1LA0RD_1LC0LA p j E).
    exact (srun_sound tm true true chb_0RB0LC_1RC0RB_1LA0RD_1LC0LA B0_0RB0LC_1RC0RB_1LA0RD_1LC0LA BB1_0RB0LC_1RC0RB_1LA0RD_1LC0LA 6 8
             run_boot_0RB0LC_1RC0RB_1LA0RD_1LC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 12), (cden [] [] j B1_0RB0LC_1RC0RB_1LA0RD_1LC0LA).
    split; [| exact (geo_0RB0LC_1RC0RB_1LA0RD_1LC0LA p j E)].
    rewrite (gxi_0RB0LC_1RC0RB_1LA0RD_1LC0LA j).
    exact (srun_sound tm true true che_0RB0LC_1RC0RB_1LA0RD_1LC0LA BE0_0RB0LC_1RC0RB_1LA0RD_1LC0LA B1_0RB0LC_1RC0RB_1LA0RD_1LC0LA 6 12
             run_exit_0RB0LC_1RC0RB_1LA0RD_1LC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_1RC0RB_1LA0RD_1LC0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1RC0RB_1LA0RD_1LC0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_1RC0RB_1LA0RD_1LC0LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_1RC0RB_1LA0RD_1LC0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 7.
  assert (H : match csteps tm 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1RC0RB_1LA0RD_1LC0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1RC0RB_1LA0RD_1LC0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1RC0RB_1LA0RD_1LC0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1RC0RB_1LA0RD_1LC0LA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB0LC_1RC0RB_1LA0RD_1LC0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0LC_1RC0RB_1LA0RD_1LC0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB0LC_1RC0RB_1LA0RD_1LC0LA t p (pow2 j)).
  - exists (6 * j + 8), (cden [] [] j BB1_0RB0LC_1RC0RB_1LA0RD_1LC0LA). split;
      [| exact (gbo_0RB0LC_1RC0RB_1LA0RD_1LC0LA j)].
    rewrite (gso_0RB0LC_1RC0RB_1LA0RD_1LC0LA p j E).
    exact (srun_sound tm true true chb_0RB0LC_1RC0RB_1LA0RD_1LC0LA B0_0RB0LC_1RC0RB_1LA0RD_1LC0LA BB1_0RB0LC_1RC0RB_1LA0RD_1LC0LA 6 8
             run_boot_0RB0LC_1RC0RB_1LA0RD_1LC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB0LC_1RC0RB_1LA0RD_1LC0LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB0LC_1RC0RB_1LA0RD_1LC0LA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1RC0RB_1LA0RD_1LC0LA : forall t, ~ In t pins_0RB0LC_1RC0RB_1LA0RD_1LC0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
