Lemma fire_0RB0LC_1RC0RB_1LA0RD_1LC1RC : forall t, ~ In t pins_0RB0LC_1RC0RB_1LA0RD_1LC1RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
