    apply (lap_of_run tm Cc true true cho_0RB0LC_1RC1RD_0LD0LA_1RB1LA B0_0RB0LC_1RC1RD_0LD0LA_1RB1LA B1_0RB0LC_1RC1RD_0LD0LA_1RB1LA 4 8 p j' [] []).
