Lemma lapi_0RB0LC_1RC1RD_1LC1LA_1LC1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
