Lemma lbl_0RB0LC_1RC1RD_1LC1LA_1LC1RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LC_1RC1RD_1LC1LA_1LC1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LC_1RC1RD_1LC1LA_1LC1RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LC_1RC1RD_1LC1LA_1LC1RB
             = (StA, (rep [S1;S0] (S j) ++ [S1;S1], S0, []))).
  { unfold cden, B1_0RB0LC_1RC1RD_1LC1LA_1LC1RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB0LC_1RC1RD_1LC1LA_1LC1RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB0LC_1RC1RD_1LC1LA_1LC1RB. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_0RB0LC_1RC1RD_1LC1LA_1LC1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1RC1RD_1LC1LA_1LC1RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LC_1RC1RD_1LC1LA_1LC1RB B0_0RB0LC_1RC1RD_1LC1LA_1LC1RB B1_0RB0LC_1RC1RD_1LC1LA_1LC1RB 4 8 p j' [] []).
    + exact run_ovf_0RB0LC_1RC1RD_1LC1LA_1LC1RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LC_1RC1RD_1LC1LA_1LC1RB p j' E).
    + exact (geo_0RB0LC_1RC1RD_1LC1LA_1LC1RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_1RC1RD_1LC1LA_1LC1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 4.
  assert (H : match csteps tm 4 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1RC1RD_1LC1LA_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1RC1RD_1LC1LA_1LC1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1RC1RD_1LC1LA_1LC1RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1RC1RD_1LC1LA_1LC1RB p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_0RB0LC_1RC1RD_1LC1LA_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_0RB0LC_1RC1RD_1LC1LA_1LC1RB = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_0RB0LC_1RC1RD_1LC1LA_1LC1RB p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_0RB0LC_1RC1RD_1LC1LA_1LC1RB p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1RC1RD_1LC1LA_1LC1RB : forall t, ~ In t pins_0RB0LC_1RC1RD_1LC1LA_1LC1RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_1RC1RD_1LC1LA_1LC1RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LC_1RC1RD_1LC1LA_1LC1RB
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LC_1RC1RD_1LC1LA_1LC1RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0LC_1RC1RD_1LC1LA_1LC1RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LC_1RC1RD_1LC1LA_1LC1RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LC_1RC1RD_1LC1LA_1LC1RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LC_1RC1RD_1LC1LA_1LC1RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_0RB0LC_1RC1RD_1LC1LA_1LC1RB (StD, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_0RB0LC_1RC1RD_1LC1LA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB0LC_1RC1RD_1LC1LA_1LC1RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_0RB0LC_1RC1RD_1LC1LA_1LC1RB : NeverQuasiHaltsTr tmm_0RB0LC_1RC1RD_1LC1LA_1LC1RB.
Proof.
  apply (glue_neverqhtr tmm_0RB0LC_1RC1RD_1LC1LA_1LC1RB pins_0RB0LC_1RC1RD_1LC1LA_1LC1RB Cc 1).
  - exact boot_0RB0LC_1RC1RD_1LC1LA_1LC1RB.
  - intros p _. apply lap_0RB0LC_1RC1RD_1LC1LA_1LC1RB.
  - intros t Ht p _. apply fire_0RB0LC_1RC1RD_1LC1LA_1LC1RB. exact Ht.
Qed.

Theorem nqhtr_0RB0LC_1RC1RD_1LC1LA_1LC1RB : NeverQuasiHaltsTr tm_0RB0LC_1RC1RD_1LC1LA_1LC1RB.
Proof. apply (neverqhtr_mirror tm_0RB0LC_1RC1RD_1LC1LA_1LC1RB). rewrite mirror_ok_0RB0LC_1RC1RD_1LC1LA_1LC1RB. exact nqhtrm_0RB0LC_1RC1RD_1LC1LA_1LC1RB. Qed.

Theorem nonhalt_0RB0LC_1RC1RD_1LC1LA_1LC1RB : NonHalt tm_0RB0LC_1RC1RD_1LC1LA_1LC1RB.
Proof. apply never_qh_tr_nonhalt, nqhtr_0RB0LC_1RC1RD_1LC1LA_1LC1RB. Qed.

