    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LD_0LC1RD_0RD1LA_1LC1RB (StA, S1)).
    intros p1 j1 E1.
    exact (firex_0RB0LD_0LC1RD_0RD1LA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LD_0LC1RD_0RD1LA_1LC1RB (StB, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0LD_0LC1RD_0RD1LA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LD_0LC1RD_0RD1LA_1LC1RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LD_0LC1RD_0RD1LA_1LC1RB (StC, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0LD_0LC1RD_0RD1LA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3; SCycR 4; SWin 1; SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LD_0LC1RD_0RD1LA_1LC1RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LD_0LC1RD_0RD1LA_1LC1RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LD_0LC1RD_0RD1LA_1LC1RB (StD, S1)).
    intros p1 j1 E1.
    exact (firex_0RB0LD_0LC1RD_0RD1LA_1LC1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

