Definition mk_0RB0LD_0RC0LD_1LD1RC_0LA1LA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB0LD_0RC0LD_1LD1RC_0LA1LA.

(** 0RB0LD_0RC0LD_1LD1RC_0LA1LA *)
(** 0RB0LD_0RC0LD_1LD1RC_0LA1LA -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LD_0RC0LD_1LD1RC_0LA1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StC
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S1 DL StA end.

(** Its mirror 0LB0RD_0LC0RD_1RD1LC_0RA1RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LD_0RC0LD_1LD1RC_0LA1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S1 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LD_0RC0LD_1LD1RC_0LA1LA : list Instr := [].
Definition tmw_0RB0LD_0RC0LD_1LD1RC_0LA1LA : TM := tm_wrap_trs tmm_0RB0LD_0RC0LD_1LD1RC_0LA1LA pins_0RB0LD_0RC0LD_1LD1RC_0LA1LA.
