(** 0RB0LD_0RC1RC_1LA1RB_0LA1RD *)
(** 0RB0LD_0RC1RC_1LA1RB_0LA1RD -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LD_0RC1RC_1LA1RB_0LA1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S1 DR StD end.

(** Its mirror 0LB0RD_0LC1LC_1RA1LB_0RA1LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LD_0RC1RC_1LA1RB_0LA1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DL StC
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LD_0RC1RC_1LA1RB_0LA1RD : list Instr := [].
Definition tmw_0RB0LD_0RC1RC_1LA1RB_0LA1RD : TM := tm_wrap_trs tmm_0RB0LD_0RC1RC_1LA1RB_0LA1RD pins_0RB0LD_0RC1RC_1LA1RB_0LA1RD.
Local Notation tm := tmw_0RB0LD_0RC1RC_1LA1RB_0LA1RD.

Lemma mirror_ok_0RB0LD_0RC1RC_1LA1RB_0LA1RD : mirror_tm tm_0RB0LD_0RC1RC_1LA1RB_0LA1RD = tmm_0RB0LD_0RC1RC_1LA1RB_0LA1RD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

